/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    next clicked();

    FormRun                 formRun = this.formRun();
    FormDataSource          prodParmReleaseDS = formRun.dataSource(formDataSourceStr(ProdParmRelease,ProdParmRelease));
    ProdParmRelease         prodParmRelease = prodParmReleaseDS.cursor();

    SRSPrintDestinationSettings printJobSettings;

    printJobSettings = new SRSPrintDestinationSettings(prodParmRelease.AVASetupPrintProdRunMap);
    SrsReportRunUtil::showSettingsDialog(printJobSettings);
    prodParmRelease.AVASetupPrintProdRunMap = printJobSettings.pack();
}
